(function(global){'use strict';const PREGNANCY_FORBIDDEN=['合谷','三阴交','昆仑','至阴','肩井','缺盆','天枢','次髎','中极','关元','石门','急脉','血海'];const DEEP_FORBIDDEN=['风府','哑门','风池','天柱','颈动脉窦','人迎','晴明','承泣','球后','玉枕'];const ORGAN_AREA=['肺俞','心俞','膈俞','肝俞','脾俞','肾俞','肩井','云门','中府','期门','日月','章门','大包'];const SI_ZONG_XUE=[{area:'头面',points:['合谷'],hint:'面口合谷收'},{area:'头项',points:['列缺'],hint:'头项寻列缺'},{area:'腰背',points:['委中'],hint:'腰背委中求'},{area:'肚腹',points:['足三里'],hint:'肚腹三里留'}];let extraRules=[];async function load(){try{const r=await fetch('data/acup-rules.json');if(r.ok){const j=await r.json();extraRules=j.rules||j||[];}}catch(e){}}
function check(ctx){const hits=[];const c=ctx.case||{};const pts=ctx.points||[];const names=new Set(pts.map(p=>(p.name||'').trim()));const patient=ctx.patient||{};const zheng=(ctx.zhengInput||'').replace(/\s/g,'');const refZheng=(c.syndrome_differentiation||c.zheng_hou||'').replace(/\s/g,'');if(!zheng){hits.push(mk('ACU-ZH-01','ZHENG',error('未填写辨证'),'请先完成辨证，再据证选穴。'));}else if(refZheng&&zheng!==refZheng&&refZheng.indexOf(zheng)<0&&zheng.indexOf(refZheng)<0){hits.push(mk('ACU-ZH-02','ZHENG',error('辨证与参考证型不符'),'学生辨证“'+zheng+'”，参考证型“'+refZheng+'”。请结合经络循行重新判断。','参考证型：'+refZheng));}
if(pts.length===0){hits.push(mk('ACU-PT-01','POINTS',error('未选择任何穴位'),'请根据辨证选择主穴与配穴。'));return{hits,score:score(hits)};}
if(patient.isPregnant){PREGNANCY_FORBIDDEN.forEach(p=>{if(names.has(p)){hits.push(mk('ACU-PG-'+p,'SAFETY',error('孕妇禁针：'+p),p+'为孕妇禁/慎针穴，妊娠期间尤其妊娠3个月内禁针，以免堕胎。'));}});}
DEEP_FORBIDDEN.forEach(p=>{if(names.has(p)){hits.push(mk('ACU-DF-'+p,'SAFETY',warn('危险腧穴：'+p),p+'深部邻近延髓/大血管，应严格控制针刺角度与深度，风府、哑门禁向上深刺。'));}});ORGAN_AREA.forEach(p=>{if(names.has(p)){hits.push(mk('ACU-OR-'+p,'SAFETY',warn(p+'应斜刺/浅刺'),p+'邻近重要脏器，应斜刺0.5-0.8寸，不可直刺深刺，以免气胸/刺伤脏器。'));}});const refMain=(c.reference_points||c.main_points||[]).map(p=>(typeof p==='string'?p:p.name));if(refMain.length>0){const hit=refMain.find(p=>names.has(p));if(!hit){hits.push(mk('ACU-MN-01','POINTS',warn('未选中参考主穴'),'参考主穴包括：'+refMain.join('、')+'。请结合经脉循行与主治重新选穴。'));}}
const hasMethod=pts.some(p=>p.method&&p.method.indexOf('补')>=0||p.method.indexOf('泻')>=0||p.method.indexOf('平')>=0);if(!hasMethod){hits.push(mk('ACU-MD-01','METHOD',warn('未标注补泻手法'),'应根据虚/实/寒热补泻：虚证用补法，实证用泻法，虚实不明显用平补平泻。'));}
pts.forEach(p=>{const m=parseFloat(p.retainMin);if(!isNaN(m)&&m>60){hits.push(mk('ACU-RT-01','METHOD',warn(p.name+'留针时间过长'),p.name+'留针'+m+'分钟，一般留针15-20分钟，慢性病可至30分钟，过长易滞针/晕针。'));}});return{hits,score:score(hits)};}
const DIMS=[{key:'zheng',name:'辨证准确性',weight:20},{key:'main',name:'主穴选择',weight:30},{key:'peixue',name:'配穴合理性',weight:15},{key:'method',name:'补泻手法规范',weight:15},{key:'safety',name:'安全禁忌',weight:20}];function score(hits){const dimMap={zheng:[],main:[],peixue:[],method:[],safety:[]};(hits||[]).forEach(h=>{if(h.group==='ZHENG')dimMap.zheng.push(h);else if(h.group==='POINTS')dimMap.main.push(h);else if(h.group==='METHOD')dimMap.method.push(h);else if(h.group==='SAFETY')dimMap.safety.push(h);else dimMap.peixue.push(h);});const dimResult={};let total=0;DIMS.forEach(d=>{const hs=dimMap[d.key]||[];let ded=0;hs.forEach(h=>ded+=h.severity==='error'?d.weight*0.8:d.weight*0.3);ded=Math.min(ded,d.weight);dimResult[d.key]={name:d.name,weight:d.weight,hits:hs,deduction:ded,score:d.weight-ded};total+=d.weight-ded;});return{total:Math.round(total*10)/10,dims:dimResult,errorCount:(hits||[]).filter(h=>h.severity==='error').length,warnCount:(hits||[]).filter(h=>h.severity==='warn').length};}
function mk(id,group,sev,message,suggestion,basis){return{rule_id:id,group,title:sev.title,severity:sev.severity,message:message,suggestion:suggestion||'',basis:basis||''};}
function error(title){return{severity:'error',title:title};}
function warn(title){return{severity:'warn',title:title};}
global.ACUPENGINE={load,check,score,DIMS,PREGNANCY_FORBIDDEN,DEEP_FORBIDDEN};})(window);